INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(49011, 'Zechariah 8:10', 'Zechariah', 8, 10, 'د هغه وخت نه مخکښې د انسان او ځناور چا دپاره هم د مزدورۍ پېسې نۀ وې. هيڅ څوک هم خپل کاروبار ته د خپلو دشمنانو په وجه په حفاظت سره نۀ شو تلے، ځکه چې ما هر سړے د خپل ګاونډى دشمن کړے وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah8_verse_10.mp3', '', 1761754199, 1761754199),
(49012, 'Zechariah 8:11', 'Zechariah', 8, 11, 'خو زۀ به اوس د دې خلقو پاتې شوو سره داسې معامله ونۀ کړم لکه چې ما مخکښې کړې وه،“ مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah8_verse_11.mp3', '', 1761754199, 1761754199),
(49013, 'Zechariah 8:12', 'Zechariah', 8, 12, '”تخم به په خير سره کَرلے کيږى، د انګورو بوټى به ښۀ مېوه کوى، زمکه به خپل فصلونه کوى، او آسمانونه به پرخه ورَوى. زۀ به دا هر څۀ د ميراث په توګه د دې خلقو ژوندى پاتې شوو ته ورکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah8_verse_12.mp3', '', 1761754199, 1761754199),
(49014, 'Zechariah 8:13', 'Zechariah', 8, 13, 'څنګه چې تۀ د قومونو دپاره د لعنت نښه وې، اے يهوداه او اِسرائيله، نو داسې به زۀ تا بچ کړم، او تۀ به د برکت سبب وګرځې. مۀ يرېږه، او تکړه شه.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah8_verse_13.mp3', '', 1761754199, 1761754199),
(49015, 'Zechariah 8:14', 'Zechariah', 8, 14, 'مالِک خُدائ ربُ الافواج دا فرمائى، ”څنګه چې ما په تاسو باندې د افت راوستلو پخه فېصله وکړه او هيڅ رحم مې ونۀ کړو کله چې ستاسو پلار نيکۀ زۀ غصه کړم،“ مالِک خُدائ ربُ الافواج فرمائى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah8_verse_14.mp3', '', 1761754199, 1761754199),
(49016, 'Zechariah 8:15', 'Zechariah', 8, 15, '”نو اوس ما پخه اراده کړې ده چې يروشلم او يهوداه ته به برکت ورکړم. يرېږه مۀ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah8_verse_15.mp3', '', 1761754199, 1761754199),
(49017, 'Zechariah 8:16', 'Zechariah', 8, 16, 'دا هغه کارونه دى چې تاسو به يې کوئ، يو بل ته رښتيا خبره کوئ. او په خپل عدالت کښې د اِنصاف نه کار اخلئ، نو دا به امن راولى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah8_verse_16.mp3', '', 1761754199, 1761754199),
(49018, 'Zechariah 8:17', 'Zechariah', 8, 17, 'د خپل ګاونډى خلاف خرابې منصوبې مۀ جوړَوئ، او د دروغو قسمونو خوړلو سره مينه مۀ کوئ. زۀ د دې ټولو څيزونو نه نفرت کوم،“ مالِک خُدائ فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah8_verse_17.mp3', '', 1761754199, 1761754199),
(49019, 'Zechariah 8:18', 'Zechariah', 8, 18, 'بيا د مالِک خُدائ ربُ الافواج کلام په ما نازل شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah8_verse_18.mp3', '', 1761754199, 1761754199),
(49020, 'Zechariah 8:19', 'Zechariah', 8, 19, 'دا هغه څۀ دى چې مالِک خُدائ ربُ الافواج يې فرمائى، ”د يهوداه دپاره د څلورمې، پينځمې، اوومې او لسمې مياشت روژې نيول به د خوشحالۍ موقعې او د خوشحالۍ اخترونه وى. په دې وجه رښتيا او امن سره مينه ساتئ.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah8_verse_19.mp3', '', 1761754199, 1761754199),
(49021, 'Zechariah 8:20', 'Zechariah', 8, 20, 'دا هغه څۀ دى چې مالِک خُدائ ربُ الافواج يې فرمائى، هغه وخت را روان دے چې ”ډېر خلق او د ډېرو ښارونو اوسېدونکى به يروشلم ته راشى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah8_verse_20.mp3', '', 1761754199, 1761754199),
(49022, 'Zechariah 8:21', 'Zechariah', 8, 21, 'او د يو ښار خلق به بل ته ځى او وائى به، راځئ چې په شريکه د مالِک خُدائ نه سوال وکړُو او د مالِک خُدائ ربُ الافواج لټون وکړُو. زۀ په خپله هم ورځمه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah8_verse_21.mp3', '', 1761754199, 1761754199),
(49023, 'Zechariah 8:22', 'Zechariah', 8, 22, 'او ډېر خلق او طاقتور قومونه به يروشلم ته راشى چې د مالِک خُدائ ربُ الافواج لټون وکړى او د هغۀ نه برکت وغواړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah8_verse_22.mp3', '', 1761754199, 1761754199),
(49024, 'Zechariah 8:23', 'Zechariah', 8, 23, 'دا هغه څۀ دى چې مالِک خُدائ ربُ الافواج يې فرمائى، ”په هغه ورځو کښې به لس سړى د ټولو ژبو او قومونو نه هر يو د يو يهودى د چُوغې لمنه کلکه ونيسى او وائى به، مونږ پرېږده چې تا سره لاړ شُو، ځکه چې مونږ اورېدلى دى چې مالِک خُدائ ستا مل دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah8_verse_23.mp3', '', 1761754199, 1761754199),
(49025, 'Joshua 4:1', 'Joshua', 4, 1, 'کله چې ټول قوم د اردن د سیند څخه تېر شو، څښتن یوشع ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua4_verse_1.mp3', '', 1761754199, 1761754199),
(49026, 'Joshua 4:2', 'Joshua', 4, 2, '«د اسراییلو د قوم څخه دولس تنه وټاکه یعنې د هرې قبیلې څخه یو یو کس', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua4_verse_2.mp3', '', 1761754199, 1761754199),
(49027, 'Joshua 4:3', 'Joshua', 4, 3, 'او هغوی ته حکم وکړه چې د اردن د سیند د منځ څخه یعنې د هماغه ځای څخه چې کاهنان ولاړ وو، دولس تیږې راواخلي. هغوی ته ووایه چې دا تیږې د ځان سره یوسي او په هغه ځای کې یې کېږدي چې تاسو نن شپه په کې خېمې ودروئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua4_verse_3.mp3', '', 1761754199, 1761754199),
(49028, 'Joshua 4:4', 'Joshua', 4, 4, 'نو یوشع هغه دولس کسان چې هغه غوره کړي وو، راوغوښتل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua4_verse_4.mp3', '', 1761754199, 1761754199),
(49029, 'Joshua 4:5', 'Joshua', 4, 5, 'او هغوی ته یې وویل: «د اردن د سیند منځ ته هغه ځای ته چې د لوظ صندوق په کې دی، لاړ شئ. تاسو هر یو د اسراییلو د قبیلو د شمېر له مخې یوه یوه تیږه واخلئ او په خپلو اوږو باندې یې کېږدئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua4_verse_5.mp3', '', 1761754199, 1761754199),
(49030, 'Joshua 4:6', 'Joshua', 4, 6, 'دا تیږې به خلکو ته هغه کارونه ور په یادوي چې څښتن کړي دي. په راتلونکې کې کله چې ستاسو اولادونه درڅخه پوښتنه وکړي چې دا تیږې ستاسو دپاره څه معنی لري؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua4_verse_6.mp3', '', 1761754199, 1761754199),
(49031, 'Joshua 4:7', 'Joshua', 4, 7, 'نو تاسو به هغوی ته وایئ کله چې د څښتن د لوظ صندوق د اردن د سیند څخه تېرېده، نو د سیند اوبه ودرېدلې. دا تیږې به تل د اسراییلو قوم ته دا خبره ور په یادوي چې دلته څه پېښ شول.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua4_verse_7.mp3', '', 1761754199, 1761754199),
(49032, 'Joshua 4:8', 'Joshua', 4, 8, 'هغو کسانو د یوشع حکمونه په ځای کړل. څنګه چې څښتن یوشع ته حکم کړی ؤ، هغوی د اردن د سیند د منځ څخه دولس تیږې راواخیستې یعنې د اسراییلو د هرې قبیلې دپاره یوه تیږه وه. هغوی دا تیږې د خېمو د ودرولو ځای ته یووړې او هلته یې کېښودلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua4_verse_8.mp3', '', 1761754199, 1761754199),
(49033, 'Joshua 4:9', 'Joshua', 4, 9, 'یوشع د اردن د سیند په منځ کې چې د لوظ د صندوق وړونکي کاهنان په کې ولاړ وو، هم دولس تیږې ودرولې. (هغه تیږې تر اوسه پورې هلته دي.)', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua4_verse_9.mp3', '', 1761754199, 1761754199),
(49034, 'Joshua 4:10', 'Joshua', 4, 10, 'کاهنان تر هغه وخته پورې د اردن د سیند په منځ کې ولاړ پاتې شول، ترڅو چې قوم هغه ټول کارونه سرته ورسول چې څښتن په یوشع باندې د هغو حکم کړی ؤ. دا هغه څه وو چې موسی هم مخکې یوشع ته حکم کړی ؤ. نو قوم په بیړه د اردن د سیند څخه تېر شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua4_verse_10.mp3', '', 1761754199, 1761754199),
(49035, 'Joshua 4:11', 'Joshua', 4, 11, 'کله چې هغوی ټول بلې غاړې ته پورې وتل، نو کاهنان د څښتن د لوظ د صندوق سره د قوم په مخکې پورې وتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua4_verse_11.mp3', '', 1761754199, 1761754199),
(49036, 'Joshua 4:12', 'Joshua', 4, 12, 'د روبین او جاد د قبیلو او د منسي د نیمې قبیلې کسان د جګړې دپاره تیار وو او لکه څنګه چې موسی هغوی ته ویلي وو، هغوی د پاتې قوم په مخکې پورې وتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua4_verse_12.mp3', '', 1761754199, 1761754199),
(49037, 'Joshua 4:13', 'Joshua', 4, 13, 'شاوخوا څلوېښت زره کسان د جګړې دپاره تیار وو او هغوی د څښتن په حضور کې هغه ډاګ ته چې اریحا ته نژدې ؤ، ورتېر شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua4_verse_13.mp3', '', 1761754199, 1761754199),
(49038, 'Joshua 4:14', 'Joshua', 4, 14, 'په هغه ورځ څښتن یوشع د ټولو اسراییلو په نظر کې سرلوړی کړ. ترڅو پورې چې هغه ژوندی ؤ هغوی د هغه درناوی کاوه، لکه څنګه چې هغوی د موسی درناوی کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua4_verse_14.mp3', '', 1761754199, 1761754199),
(49039, 'Joshua 4:15', 'Joshua', 4, 15, 'بیا څښتن یوشع ته وویل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua4_verse_15.mp3', '', 1761754199, 1761754199),
(49040, 'Joshua 4:16', 'Joshua', 4, 16, 'چې په هغو کاهنانو باندې چې د لوظ صندوق انتقالوي، امر وکړي چې د اردن د سیند څخه راووځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua4_verse_16.mp3', '', 1761754199, 1761754199),
(49041, 'Joshua 4:17', 'Joshua', 4, 17, 'یوشع هماغسې وکړل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua4_verse_17.mp3', '', 1761754199, 1761754199),
(49042, 'Joshua 4:18', 'Joshua', 4, 18, 'او کله چې کاهنان د سیند غاړې ته ورسېدل، نو سمدلاسه د سیند اوبو بېرته په بهېدلو پیل وکړ او د سېلاب په شان بیا د سیند د غاړو څخه پورته شولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua4_verse_18.mp3', '', 1761754199, 1761754199),
(49043, 'Joshua 4:19', 'Joshua', 4, 19, 'د لومړۍ میاشتې په لسمه ورځ قوم د اردن د سیند څخه تېر شو او په جلجال کې یې چې د اریحا ختیځې خواته پروت ؤ، خېمې ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua4_verse_19.mp3', '', 1761754199, 1761754199),
(49044, 'Joshua 4:20', 'Joshua', 4, 20, 'یوشع په جلجال کې هغه دولس تیږې ودرولې چې هغوی د اردن د سیند څخه راویستلې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua4_verse_20.mp3', '', 1761754199, 1761754199),
(49045, 'Joshua 4:21', 'Joshua', 4, 21, 'هغه د اسراییلو خلکو ته وویل: «په راتلونکې کې کله چې ستاسو اولادونه ستاسو څخه پوښتنه وکړي چې دا تیږې څه معنی لري؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua4_verse_21.mp3', '', 1761754199, 1761754199),
(49046, 'Joshua 4:22', 'Joshua', 4, 22, 'تاسو به هغوی ته د هغه وخت په اړه ووایئ چې اسراییلیان د اردن په سیند کې په وچه ځمکه باندې پورې وتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua4_verse_22.mp3', '', 1761754199, 1761754199),
(49047, 'Joshua 4:23', 'Joshua', 4, 23, 'هغوی ته ووایئ چې زمونږ څښتن خدای زمونږ په خاطر د اردن د سیند اوبه وچې کړې، ترڅو مونږ ورڅخه تېر شو، لکه څنګه چې هغه زمونږ دپاره د سرې بحیرې اوبه وچې کړې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua4_verse_23.mp3', '', 1761754199, 1761754199),
(49048, 'Joshua 4:24', 'Joshua', 4, 24, 'هغه دا کارونه ځکه وکړل چې د ځمکې په مخ ټول قومونه پوه شي چې د څښتن قدرت څومره زیات دی او تاسو به د تل دپاره د خپل څښتن خدای څخه وېره کوئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua4_verse_24.mp3', '', 1761754199, 1761754199),
(49049, 'Psalms 112:1', 'Psalms', 112, 1, 'د څښتن ثنا او صفت وکړئ! بختور دی هغه څوک چې کړي وېره له څښتنه چې ډېر په خوښۍ سره مني د هغه حکمونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms112_verse_1.mp3', '', 1761754199, 1761754199),
(49050, 'Psalms 112:2', 'Psalms', 112, 2, 'د هغه اولادونه به شي قوي وطن کې او د نېکو خلکو نسل به برکت ومومي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms112_verse_2.mp3', '', 1761754199, 1761754199),
(49051, 'Psalms 112:3', 'Psalms', 112, 3, 'وي به شتمنه او دولتمنده کورنۍ د هغه وي به نېکمرغه تر ابده پورې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms112_verse_3.mp3', '', 1761754199, 1761754199),
(49052, 'Psalms 112:4', 'Psalms', 112, 4, 'نېکانو خلکو ته ځلیږي په تیاره کې رڼا څوک چې مهربانه، زړه سواندي او عادل اوسي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms112_verse_4.mp3', '', 1761754199, 1761754199),
(49053, 'Psalms 112:5', 'Psalms', 112, 5, 'بختور دی هغه څوک چې وي سخي قرض ورکولو کې چې چلوي خپل کاروبار په انصاف سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms112_verse_5.mp3', '', 1761754199, 1761754199),
(49054, 'Psalms 112:6', 'Psalms', 112, 6, 'ناکام به نه شي په هېڅ وخت کې نېک عمله سړی نوم به یې یادیږي د همېش دپاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms112_verse_6.mp3', '', 1761754199, 1761754199),
(49055, 'Psalms 112:7', 'Psalms', 112, 7, 'نه به وېریږي هغه له بد خبر څخه ځکه چې زړه یې دی قوي، لري توکل په څښتن', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms112_verse_7.mp3', '', 1761754199, 1761754199),
(49056, 'Psalms 112:8', 'Psalms', 112, 8, 'زړه یې ټینګ دی او نه وېریږي هغه به ویني په رښتیا د دښمنانو ماتې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms112_verse_8.mp3', '', 1761754199, 1761754199),
(49057, 'Psalms 112:9', 'Psalms', 112, 9, 'په سخاوت سره کومک کړي محتاجانو سره د هغه نېک اعمال د تل دپاره پاتې کیږي وي به قوي او درناوی به یې کیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms112_verse_9.mp3', '', 1761754199, 1761754199),
(49058, 'Psalms 112:10', 'Psalms', 112, 10, 'بدکاران چې دا ګوري په قهریږي به خپل غاښونه به چیچي او ورکیږي به دوی ارمان به نه شي پوره د هغوی هېڅکله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms112_verse_10.mp3', '', 1761754199, 1761754199),
(49059, 'Jeremiah 38:1', 'Jeremiah', 38, 1, 'سفطياه د متان زوئ، جدلياه د فشحور زوئ، يهوکل د شلمياه زوئ او فشحور د مُلکياه زوئ هغه څۀ واورېدل چې يرمياه ټولو خلقو ته وفرمائيل چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah38_verse_1.mp3', '', 1761754199, 1761754199),
(49060, 'Jeremiah 38:2', 'Jeremiah', 38, 2, '”مالِک خُدائ فرمائى چې، هر څوک چې په دې ښار کښې ايسار شى نو هغوئ به په جنګ، قحط او د وبا په وجه مړۀ شى. خو هر څوک چې خپل ځان بابليانو ته حواله کړى، نو هغوئ به ژوندى پاتې شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah38_verse_2.mp3', '', 1761754199, 1761754199),
(49061, 'Jeremiah 38:3', 'Jeremiah', 38, 3, 'مالِک خُدائ داسې هم فرمائى چې، دا ښار به په يقين سره د بابل د بادشاه فوجيانو ته حواله کړے شى او هغوئ به يې قبضه کړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah38_verse_3.mp3', '', 1761754199, 1761754199),
(49062, 'Jeremiah 38:4', 'Jeremiah', 38, 4, 'نو بيا آفسران بادشاه له ورغلل او ورته يې ووئيل چې، ”دا سړے دې خامخا قتل کړے شى، ځکه چې هغه په ښار کښې زمونږ خلق او په جنګ کښې بچ شوى فوجيان په خپلو دې خبرو باندې بې‌زړۀ کوى. هغه د خلقو ښېګړه نۀ لټوى بلکې په دې خبرو سره ورته نقصان ورکوى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah38_verse_4.mp3', '', 1761754199, 1761754199),
(49063, 'Jeremiah 38:5', 'Jeremiah', 38, 5, 'صدقياه بادشاه ورته په جواب کښې ووئيل چې، ”صحيح ده، هغه اوس ستاسو په لاس کښې دے. زۀ تاسو نۀ شم منع کولے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah38_verse_5.mp3', '', 1761754199, 1761754199),
(49064, 'Jeremiah 38:6', 'Jeremiah', 38, 6, 'نو بيا هغوئ يرمياه ونيولو او په پړو يې د قېدخانې په دربار کښې ډيګۍ ته ورکوز کړو کوم چې د مُلکياه شهزاده ملکيت وو. نو په هغه ډيګۍ کښې اوبۀ نۀ وې، خو لاندې په بېخ کښې ډيرې بوختې وې او يرمياه په هغې کښې ډوب شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah38_verse_6.mp3', '', 1761754199, 1761754199),
(49065, 'Jeremiah 38:7', 'Jeremiah', 38, 7, 'خو د ايتهوپيا خصى عبيدمَلِک د دربار يو اهم شخصيت د دې نه خبر شو چې هغوئ يرمياه په ډيګۍ کښې اچولے شوے دے. په دغه وخت کښې بادشاه د بنيامين په دروازه کښې ناست وو او عدالت يې شروع کړے وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah38_verse_7.mp3', '', 1761754199, 1761754199),
(49066, 'Jeremiah 38:8', 'Jeremiah', 38, 8, 'نو عبيدمَلِک هلته لاړو او بادشاه ته يې ووئيل چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah38_verse_8.mp3', '', 1761754199, 1761754199),
(49067, 'Jeremiah 38:9', 'Jeremiah', 38, 9, '”بادشاه سلامت، دې سړو ډېر زيات بد کار وکړو په دې چې هغوئ يرمياه نبى د اوبو په ډيګۍ کښې واچولو. هغه به ډېر زر د لوږې نه مړ شى، ځکه چې په ښار کښې روټۍ ختمه شوه.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah38_verse_9.mp3', '', 1761754199, 1761754199),
(49068, 'Jeremiah 38:10', 'Jeremiah', 38, 10, 'نو بادشاه عبيدمَلِک له حُکم ورکړو چې، ”د دې ځائ نه ځان سره دېرش سړى بوځه او يرمياه د مړ کېدو نه وړاندې د هغه ډيګۍ نه راوباسه.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah38_verse_10.mp3', '', 1761754199, 1761754199),
(49069, 'Jeremiah 38:11', 'Jeremiah', 38, 11, 'نو عبيدمَلِک د ځان سره کسان واخستل او په شاهى محل کښې د خزانې نه لاندې کمرې ته لاړو او د خپل ځان سره يې څۀ زړې جامې چِرړې راواخستلې. او هغه يې يرمياه ته د پړى په ذريعه ډيګۍ ته ښکته کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah38_verse_11.mp3', '', 1761754199, 1761754199),
(49070, 'Jeremiah 38:12', 'Jeremiah', 38, 12, 'عبيدمَلِک يرمياه ته آواز ورکړو او ورته يې ووئيل چې، ”دا زړې کپړې او جامې په خپلو ترخونو کښې کېږده چې د راختو په وخت کښې دې پړے زخمى نۀ کړى.“ يرمياه هم هغه شان وکړل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah38_verse_12.mp3', '', 1761754199, 1761754199),
(49071, 'Jeremiah 38:13', 'Jeremiah', 38, 13, 'او هغوئ هغه د ډيګۍ نه په پړو راوويستلو. او بيا يرمياه د فوجيانو په چاوڼۍ کښې بندى پاتې شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah38_verse_13.mp3', '', 1761754199, 1761754199),
(49072, 'Jeremiah 38:14', 'Jeremiah', 38, 14, 'يوه ورځ صدقياه بادشاه، يرمياه پسې کسان ورولېږل او هغه يې خپل ځان ته د مالِک خُدائ د کور درېمې دروازې ته راوستو. بادشاه ورته ووئيل چې، ”زۀ غواړم چې تا نه يو څو تپوسونه وکړم. نو د هيڅ قسمه حقيقت او رښتيا پټولو کوشش مۀ کوه.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah38_verse_14.mp3', '', 1761754199, 1761754199),
(49073, 'Jeremiah 38:15', 'Jeremiah', 38, 15, 'يرمياه ورته وفرمائيل، ”کۀ چرې زۀ تاسو ته رښتيا ووايم، نو تاسو به ما مړ کړئ. او کۀ چرې زۀ تاسو ته نصيحت وکړم، نو تاسو به ما ته غوږ ونۀ نيسئ.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah38_verse_15.mp3', '', 1761754199, 1761754199),
(49074, 'Jeremiah 38:16', 'Jeremiah', 38, 16, 'نو بيا صدقياه بادشاه د هغۀ سره په پټه وعده وکړه او ورته يې ووئيل چې، ”زۀ په مالِک خُدائ درته قسم خورم څوک چې ژوندے دے، او څوک چې مونږ ته ژوند راکوى، نۀ به زۀ تا مړ کړم او نۀ به دې هغه کسانو ته حواله کړم څوک چې تا وژل غواړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah38_verse_16.mp3', '', 1761754199, 1761754199),
(49075, 'Jeremiah 38:17', 'Jeremiah', 38, 17, 'نو په هغه وخت کښې بيا يرمياه صدقياه د يهوداه بادشاه ته وفرمائيل چې، ”مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک داسې فرمائى چې، کۀ چرې تاسو خپل ځان د بابل آفسرانو ته حواله کړئ، تاسو او ستاسو خاندان به ژوندى پاتې شئ، او دا ښار به د سوزېدو نه بچ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah38_verse_17.mp3', '', 1761754199, 1761754199),
(49076, 'Jeremiah 38:18', 'Jeremiah', 38, 18, 'خو کۀ تاسو د خپل ځان د حواله کېدو نه اِنکار وکړئ، نو دا ښار به بابليانو ته حواله کړے شى، او هغوئ به دا ښار د سر نه تر آخره پورې وسوزوى. او تاسو به ترې نۀ شئ تښتېدلے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah38_verse_18.mp3', '', 1761754199, 1761754199),
(49077, 'Jeremiah 38:19', 'Jeremiah', 38, 19, 'خو صدقياه بادشاه يرمياه ته ووئيل چې، ”زۀ د خپل مُلک د هغه خلقو نه يرېږم چا چې غدارى وکړه او بابليانو له ورغلل، کېدے شى چې د بابل فوجيان ما هغوئ ته حواله کړى او بيا به هغوئ ما سره بد سلوک وکړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah38_verse_19.mp3', '', 1761754199, 1761754199),
(49078, 'Jeremiah 38:20', 'Jeremiah', 38, 20, 'يرمياه ورته وفرمائيل چې، ”هغوئ به تاسو چا ته نۀ حواله کوى کۀ چرې تۀ د مالِک خُدائ تابعدارى غوره کړې. هغه به ستا ژوند بچ کړى او تا ته به خير شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah38_verse_20.mp3', '', 1761754199, 1761754199),
(49079, 'Jeremiah 38:21', 'Jeremiah', 38, 21, 'خو کۀ چرې تاسو نۀ غواړئ چې خپل ځان هغوئ ته حواله کړئ نو بيا مالِک خُدائ ما ته دا موضوع په رويا کښې ښکاره کړې ده چې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah38_verse_21.mp3', '', 1761754199, 1761754199),
(49080, 'Jeremiah 38:22', 'Jeremiah', 38, 22, 'څومره ښځې چې په دې شاهى محل کښې ژوندۍ پاتې وى نو هغوئ به فوجيان د بابليانو آفسرانو ته ستاسو نه بوځى. نو بيا به د تلو په وخت دا ښځې تاسو ته داسې پېغور درکوى او درته به وائى چې، ”ستاسو څومره ښۀ دوستان وُو، ټولو تاسو سره دوکه وکړه او بې‌لارې يې کړئ. او کله چې ستا پښه په دلدل کښې کېښودے شوه نو بيا يې تۀ خپل نصيب ته پرېښودلې.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah38_verse_22.mp3', '', 1761754199, 1761754199),
(49081, 'Jeremiah 38:23', 'Jeremiah', 38, 23, 'ستاسو ټولې ښځې او ماشومان به بابليانو ته بهر راوويستلے شى، او تۀ به هم د هغوئ د نيولو نه بچ نۀ شې. تاسو به د بابل د بادشاه له خوا ګرفتار شئ، او دا ښار به وسوزيږى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah38_verse_23.mp3', '', 1761754199, 1761754199),
(49082, 'Jeremiah 38:24', 'Jeremiah', 38, 24, 'نو بيا صدقياه يرمياه ته ووئيل چې، ”چا ته داسې ونۀ وائې چې تا ما ته دا خبره وکړه، ګنې تۀ به مړ ‎شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah38_verse_24.mp3', '', 1761754199, 1761754199),
(49083, 'Jeremiah 38:25', 'Jeremiah', 38, 25, 'کۀ آفسرانو ته زما او ستا د ملاقات پته ولګى او راشى او ستا نه تپوس وکړى چې تاسو يو بل ته څۀ ووئيل نو مونږ ته سمه خبره وکړه او دروغ مۀ وايه ګنې مړ به دې کړُو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah38_verse_25.mp3', '', 1761754199, 1761754199),
(49084, 'Jeremiah 38:26', 'Jeremiah', 38, 26, 'نو بيا هغوئ ته ووايه چې ما بادشاه ته مِنت او زارى وکړه چې بيا مې د يونتن د کور تاخانې ته مۀ لېږه ګنې زۀ به هلته مړ شم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah38_verse_26.mp3', '', 1761754199, 1761754199),
(49085, 'Jeremiah 38:27', 'Jeremiah', 38, 27, 'هم هغه شان وشول، لږ وخت تېر شوے نۀ وو چې د بادشاه ټول آفسران راغلل او د يرمياه نه يې تپوسونه شروع کړل چې بادشاه د څۀ دپاره راغوښتے وې. خو يرمياه د بادشاه په هداياتو عمل وکړو. خو د بادشاه او د يرمياه په مينځ کښې شوې خبرې هيچا هم نۀ وې اورېدلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah38_verse_27.mp3', '', 1761754199, 1761754199),
(49086, 'Jeremiah 38:28', 'Jeremiah', 38, 28, 'نو بيا يرمياه د دې نه وروستو د يروشلم د شکست پورې د فوجيانو په چاوڼۍ کښې بندى پاتې شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah38_verse_28.mp3', '', 1761754199, 1761754199),
(49087, 'Psalms 125:1', 'Psalms', 125, 1, 'څوک چې څښتن باندې توکل کوي دي د صهیون د غره په شان هغوی چې هېڅکله نه لړزیږي او ټینګ وي تل دپاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms125_verse_1.mp3', '', 1761754199, 1761754199),
(49088, 'Psalms 125:2', 'Psalms', 125, 2, 'لکه څنګه چې ساتنه کیږي له اورشلیم نه په غرونو له هرې خوا نه داسې څښتن کوي ساتنه د خپل قوم څخه له همدا‌اوس نه تر ابده پورې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms125_verse_2.mp3', '', 1761754199, 1761754199),
(49089, 'Psalms 125:3', 'Psalms', 125, 3, 'بدکاران به همېش نه کوي حکومت په هغې ځمکې چې ورکړل شوې ده نېکانو ته هسې نه چې نېکان خلک شي اخته بدو کارونو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms125_verse_3.mp3', '', 1761754199, 1761754199),
(49090, 'Psalms 125:4', 'Psalms', 125, 4, 'کوم خلک چې ښه وي ای څښتنه، کوه ښه ورسره د هغه چا سره چې زړونه یې پاک وي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms125_verse_4.mp3', '', 1761754199, 1761754199),
(49091, 'Psalms 125:5', 'Psalms', 125, 5, 'خو بدکارانو ته چې څښتن کله سزا ورکوي نو سزا دې ورکړي هغو کسانو ته هم چې ګرځېدلي ستا له لارې څخه سلامتي دې وي په اسراییلو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms125_verse_5.mp3', '', 1761754199, 1761754199),
(49092, 'Exodus 31:1', 'Exodus', 31, 1, 'بیا څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus31_verse_1.mp3', '', 1761754199, 1761754199),
(49093, 'Exodus 31:2', 'Exodus', 31, 2, '«ګوره، ما بزل ییل د اوري زوی او د حور لمسی د یهودا د قبیلې څخه غوره کړی دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus31_verse_2.mp3', '', 1761754199, 1761754199),
(49094, 'Exodus 31:3', 'Exodus', 31, 3, 'او هغه مې د خپل روح څخه ډک کړی دی او په هر ډول هنري کار کې مې ورته مهارت، توان او پوهه ورکړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus31_verse_3.mp3', '', 1761754199, 1761754199),
(49095, 'Exodus 31:4', 'Exodus', 31, 4, 'هغه کولای شي چې د سرو زرو، سپینو زرو او برنجو څخه ښکلي شیان جوړ کړي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus31_verse_4.mp3', '', 1761754199, 1761754199),
(49096, 'Exodus 31:5', 'Exodus', 31, 5, 'قیمتي تیږې پرې کړي او تیارې یې کړي، د لرګیو کار او هر ډول هنري کار وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus31_verse_5.mp3', '', 1761754199, 1761754199),
(49097, 'Exodus 31:6', 'Exodus', 31, 6, 'ما اهولیاب د اخیسامک زوی چې د دان له قبیلې څخه دی، د دې دپاره ټاکلی دی چې د هغه مرستیال وي. برسېره پردې ما ټولو کسبګرو ته چې د هغوی سره کار کوي، ځانګړی مهارت ورکړی دی، ترڅو وکولای شي هغه ټول شیان جوړ کړي چې په تا باندې مې حکم کړی دی:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus31_verse_6.mp3', '', 1761754199, 1761754199),
(49098, 'Exodus 31:7', 'Exodus', 31, 7, 'لکه سپېڅلې خېمه، د لوظ صندوق د سرپوښ سره چې ورباندې پروت وي او د خېمې نور ټول سامان،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus31_verse_7.mp3', '', 1761754199, 1761754199),
(49099, 'Exodus 31:8', 'Exodus', 31, 8, 'مېز او د هغه سامان، د سوچه سرو زرو څراغدان او د هغه ټول سامان، د خوشبویۍ د سوځولو دپاره د قربانۍ ځای،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus31_verse_8.mp3', '', 1761754199, 1761754199),
(49100, 'Exodus 31:9', 'Exodus', 31, 9, 'د سوځېدونکې نذرانې د قربانۍ ځای او د هغه ټول لوښي، تشت او د هغه پایه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus31_verse_9.mp3', '', 1761754199, 1761754199),
(49101, 'Exodus 31:10', 'Exodus', 31, 10, 'د هارون کاهن او د هغه د زامنو دپاره ښکلي کالي چې کله هغوی د کاهنانو په توګه خدمت کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus31_verse_10.mp3', '', 1761754199, 1761754199),
(49102, 'Exodus 31:11', 'Exodus', 31, 11, 'او د مسح کولو تېل او د سپېڅلي ځای دپاره خوشبویي. هغوی دې دا شیان هماغسې جوړ کړي لکه څنګه چې ما درته حکم کړی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus31_verse_11.mp3', '', 1761754199, 1761754199),
(49103, 'Exodus 31:12', 'Exodus', 31, 12, 'بیا څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus31_verse_12.mp3', '', 1761754199, 1761754199),
(49104, 'Exodus 31:13', 'Exodus', 31, 13, '«د اسراییلو خلکو ته داسې ووایه: تاسو باید سبت ورځ ولمانځئ. دا به تل ترتله زما او ستاسو ترمنځ یوه نښه وي، ترڅو تاسو پوه شئ چې زه څښتن یم او تاسو مې د خپل قوم په توګه ټاکلي یئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus31_verse_13.mp3', '', 1761754199, 1761754199),
(49105, 'Exodus 31:14', 'Exodus', 31, 14, 'د سبت ورځ ولمانځئ، ځکه چې دا ستاسو دپاره سپېڅلې ده. هرڅوک چې د هغې بې عزتي کوي، باید ووژل شي او هرڅوک چې په دې ورځ کار وکړي، باید زما له قوم څخه وشړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus31_verse_14.mp3', '', 1761754199, 1761754199),
(49106, 'Exodus 31:15', 'Exodus', 31, 15, 'تاسو د کار کولو دپاره شپږ ورځې لرئ، خو اوومه ورځ د سبت یعنې د ارام کولو سپېڅلې ورځ ده چې ما څښتن ته وقف کړای شوې ده. هرڅوک چې په دې ورځ کار وکړي، هغه دې ووژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus31_verse_15.mp3', '', 1761754199, 1761754199),
(49107, 'Exodus 31:16', 'Exodus', 31, 16, 'اسراییلیان دې د سبت د ورځې څخه پیروي وکړي. هغه دې د یو لوظ په توګه د تل دپاره ولمانځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus31_verse_16.mp3', '', 1761754199, 1761754199),
(49108, 'Exodus 31:17', 'Exodus', 31, 17, 'دا به تل زما او د اسراییلیانو ترمنځ یوه نښه وي، ځکه چې ما څښتن ځمکه او اسمانونه په شپږو ورځو کې جوړ کړل او په اوومه ورځ مې کار بس کړ او ارام مې وکړ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus31_verse_17.mp3', '', 1761754199, 1761754199),
(49109, 'Exodus 31:18', 'Exodus', 31, 18, 'کله چې د سینا په غره باندې څښتن د موسی سره خبرې خلاصې کړې، نو د تیږو هغه دوه لوحې چې په خپله یې ورباندې حکمونه لیکلي وو، موسی ته ورکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus31_verse_18.mp3', '', 1761754199, 1761754199),
(49110, 'Psalms 38:1', 'Psalms', 38, 1, 'کله چې ته په قهرېږې ای څښتنه نو ما مه رټه په خپل غضب سره دې ماته سزا مه راکوه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms38_verse_1.mp3', '', 1761754199, 1761754199);